			_, _, e := f.s.Store.WriteAnswer(context.Background(), id, uuid.NewString(), 0, answerPacket(v, "en"), false)
			results <- e
		}(text)
	}
	close(gate)
	wg.Wait()
	close(results)
	success, stale := 0, 0
	for e := range results {
		if e == nil {
			success++
		} else if errors.Is(e, ErrRevision) {
			stale++
		} else {
			t.Fatal(e)
		}
	}
	if success != 1 || stale != 1 {
		t.Fatal(success, stale)
	}
}
