		_ = json.NewEncoder(w).Encode(map[string]any{"id": "constructed-review", "status": "completed", "output": []any{map[string]any{"type": "message", "content": []any{map[string]any{"type": "output_text", "text": string(mustJSON(out))}}}}})
	}))
